python scripts/track_service.py --case {case_id} --advance --owner "张工"

# 6. 落库
python scripts/save_to_db.py --need output/needs/{case_id}.json --plan output/plans/{case_id}.md --tracking output/tracking/{case_id}.json --sql-only
