INSERT INTO "public"."codelabs" VALUES ('b8c9d0e1-f2a3-4567-bcde-890123456789', 'generate_import_script', '{"source_file":"data/users.csv","target_table":"users","mapping":{"name":"username","mail":"email"},"batch_size":1000}', 'import_script: { source_file: String, target_table: String, mapping: Map<String,String>, batch_size: Int, validation: Array<ValidationRule> }', 'import csv\nimport psycopg2\n\ndef import_users():\n    with open("data/users.csv") as f:\n        reader = csv.DictReader(f)\n        for row in reader:\n            # 插入数据库\n            pass\n', '{"language":"python","database":"postgresql","error_handling":"skip_and_log"}', 'import_script_generator10', '{"status":"success","files":["import_users.py","requirements.txt"]}', '{"source":"csv_file","file":"data/users.csv"}', '{"format":"python_script","target":"scripts/import/"}', '数据导入脚本生成示例数据1', 'templates/import_script.py.tmpl', 'csv_file:data/users.csv', '505cf909-5e0e-4dde-b215-74274d2cc548', '2026-08-22 15:25:00+08', '2026-08-22 15:25:00+08', NULL);
INSERT INTO "public"."codelabs" VALUES ('b2c3d4e5-f6a7-8901-bcde-f23456789012', 'generate_detail_page', '{"table":"orders","fields":["id","order_no","amount","status","user_id","created_at"],"filter":{"deleted_at":null}}', 'orders: { id: UUID, order_no: String, amount: Decimal, status: String, user_id: UUID, created_at: DateTime, deleted_at: DateTime? }', '<template>\n  <el-descriptions :column="2" border>\n    <el-descriptions-item label="订单号">{{ order.order_no }}</el-descriptions-item>\n    <el-descriptions-item label="金额">{{ order.amount }}</el-descriptions-item>\n  </el-descriptions>\n</template>', '{"layout":"descriptions","actions":["edit","delete"]}', 'detail_generator', '{"status":"success","files":["OrderDetail.vue","order.ts"]}', '{"source":"database","table":"orders"}', '{"format":"vue_component","target":"src/views/orders/"}', '订单详情页面生成示例数据', 'templates/detail_page.vue.tmpl', 'database:public.orders', '505cf909-5e0e-4dde-b215-74274d2cc548', '2026-08-16 14:20:00+08', '2026-08-16 14:20:00+08', NULL);

