INSERT INTO "public"."company" VALUES ('10000000-0000-0000-0000-000000000003', '星辰设计工作室', '深圳市南山区', '91440300MA5DKLMN3', '2025-03-10', '100万', '深圳市南山区科技园', '深圳市南山区科技园', '王芳', '13800138004', 'wangfang@star-design.cn', '王芳', '13800138004', 'hello@star-design.cn', '创意总监', 'https://star-design.cn', 'https://api.dicebear.com/7.x/identicon/svg?seed=stardesign', NULL, 1, '星辰设计 - 让创意点亮世界', '', '00000000-0000-0000-0000-000000000003', '2026-07-01 02:39:37.986211+08', '2026-07-01 02:39:37.986211+08', NULL, '星辰设计工作室专注于用户体验设计和品牌视觉设计。我们相信好的设计能够改变世界，让产品与用户之间建立更深层的情感连接。服务范围包括：UI/UX设计、品牌设计、插画设计、动效设计等。', 12, 8, 156, 'f', 'studio', '["UI设计", "UX设计", "品牌设计", "插画"]', 65000);
