INSERT INTO "public"."company" VALUES ('10000000-0000-0000-0000-000000000005', 'AI前沿探索社区', '成都市高新区', '91510100MA6TUVWX5', '2025-01-08', '50万', '成都市高新区天府大道', '成都市高新区天府大道', '赵雪', '13800138007', 'zhaoxue@aifrontier.tech', '赵雪', '13800138007', 'community@aifrontier.tech', '社区发起人', 'https://aifrontier.tech', 'https://api.dicebear.com/7.x/identicon/svg?seed=aifrontier', NULL, 0, '探索AI前沿技术，连接全球AI爱好者', '', '00000000-0000-0000-0000-000000000006', '2026-07-01 02:39:37.996928+08', '2026-07-01 02:39:37.996928+08', NULL, 'AI前沿探索社区是一个聚焦人工智能前沿技术的开发者社区。我们关注大模型、Agent、多模态、RAG等热门方向，定期举办技术分享会和黑客松活动。无论你是AI新手还是资深研究者，都能在这里找到志同道合的伙伴。', 56, 15, 289, 'f', 'community', '["人工智能", "大模型", "Agent", "RAG"]', 45000);
