-- ----------------------------
-- Table structure for long_running_task_artifact
-- ----------------------------
DROP TABLE IF EXISTS "public"."long_running_task_artifact";
CREATE TABLE "public"."long_running_task_artifact" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "task_id" uuid,
  "artifact_path" text COLLATE "pg_catalog"."default" NOT NULL,
  "artifact_type" varchar(50) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'unknown'::character varying,
  "verification_status" varchar(20) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'pending'::character varying,
  "verification_result" jsonb,
  "creator" uuid,
  "created_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz(6),
  "owner_user_id" uuid
)
;
COMMENT ON COLUMN "public"."long_running_task_artifact"."id" IS '主键UUID';
COMMENT ON COLUMN "public"."long_running_task_artifact"."task_id" IS '关联 agent_tasks.id，NULL 表示未绑定具体任务（如全局产物）';
COMMENT ON COLUMN "public"."long_running_task_artifact"."artifact_path" IS '产物落盘路径（相对 output/ 或绝对路径）';
COMMENT ON COLUMN "public"."long_running_task_artifact"."artifact_type" IS '产物类型：code/config/doc/test/report/data/artifact';
COMMENT ON COLUMN "public"."long_running_task_artifact"."verification_status" IS '校验状态：pending-待校验/verifying-校验中/passed-通过/failed-失败';
COMMENT ON COLUMN "public"."long_running_task_artifact"."verification_result" IS '结构化验核结果 JSON：{checks:[{name,passed,detail}], summary, checked_at}';
COMMENT ON COLUMN "public"."long_running_task_artifact"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限';
COMMENT ON COLUMN "public"."long_running_task_artifact"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."long_running_task_artifact"."updated_at" IS '更新时间';
COMMENT ON COLUMN "public"."long_running_task_artifact"."owner_user_id" IS '归属者（委派该任务的真人用户 uctoo_user.id）。与 creator 区分：creator 记执行者（agent 帐号），本列恒记归属真人；历史行允许 NULL。';
COMMENT ON TABLE "public"."long_running_task_artifact" IS '长程任务产物表：记录每步/每回合产出的文件或对象，含校验状态与结构化验核结果';

-- ----------------------------
-- Records of long_running_task_artifact
-- ----------------------------

-- ----------------------------
-- Table structure for long_running_task_evolution
-- ----------------------------
DROP TABLE IF EXISTS "public"."long_running_task_evolution";
CREATE TABLE "public"."long_running_task_evolution" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "agent_id" uuid,
  "round" int4 NOT NULL DEFAULT 0,
  "root_cause" text COLLATE "pg_catalog"."default",
  "optimization_plan" text COLLATE "pg_catalog"."default",
  "anti_regression" text COLLATE "pg_catalog"."default",
  "skill_md_updates" jsonb,
  "creator" uuid,
  "created_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz(6),
  "owner_user_id" uuid
)
;
COMMENT ON COLUMN "public"."long_running_task_evolution"."id" IS '主键UUID';
COMMENT ON COLUMN "public"."long_running_task_evolution"."agent_id" IS '关联 agent 配置 id，跨任务聚合自进化知识';
COMMENT ON COLUMN "public"."long_running_task_evolution"."round" IS '自进化轮次（0 起），同一 agent 下递增';
COMMENT ON COLUMN "public"."long_running_task_evolution"."root_cause" IS '根因分析：基于日志与指标定位问题根因（非表面现象）';
COMMENT ON COLUMN "public"."long_running_task_evolution"."optimization_plan" IS '增量优化方案：复用现有基础设施的改动计划';
COMMENT ON COLUMN "public"."long_running_task_evolution"."anti_regression" IS '防回退约束文本：错误行为示例（严禁复现）+ 正确行为示例';
COMMENT ON COLUMN "public"."long_running_task_evolution"."skill_md_updates" IS 'SKILL.md 变更 JSON：[{skill, section, before, after}]';
COMMENT ON COLUMN "public"."long_running_task_evolution"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限';
COMMENT ON COLUMN "public"."long_running_task_evolution"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."long_running_task_evolution"."updated_at" IS '更新时间';
COMMENT ON COLUMN "public"."long_running_task_evolution"."deleted_at" IS '软删除时间，NULL=未删除';
COMMENT ON COLUMN "public"."long_running_task_evolution"."owner_user_id" IS '归属者（委派该任务的真人用户 uctoo_user.id）。与 creator 区分：creator 记执行者（agent 帐号），本列恒记归属真人；历史行允许 NULL。';
COMMENT ON TABLE "public"."long_running_task_evolution" IS '长程任务自进化记录表：LrtSelfEvolutionLoop 五环节闭环（实测驱动→根因分析→增量优化→防回退→显式约束注入）';

-- ----------------------------
-- Records of long_running_task_evolution
-- ----------------------------

-- ----------------------------
-- Table structure for lrt_verify_job
-- ----------------------------
DROP TABLE IF EXISTS "public"."lrt_verify_job";
CREATE TABLE "public"."lrt_verify_job" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "task_id" uuid NOT NULL,
  "round" int4 NOT NULL DEFAULT 0,
  "status" varchar(32) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'pending'::character varying,
  "result" text COLLATE "pg_catalog"."default",
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz(6)
)
;
COMMENT ON COLUMN "public"."lrt_verify_job"."id" IS '主键UUID';
COMMENT ON COLUMN "public"."lrt_verify_job"."task_id" IS '关联 agent_tasks.id，标识待验核的长程任务';
COMMENT ON COLUMN "public"."lrt_verify_job"."round" IS '验核对应的宿主回合序号，从 1 起';
COMMENT ON COLUMN "public"."lrt_verify_job"."status" IS '验核状态：pending-待验核/processing-验核中/done-已完成/failed-失败/skipped-已跳过';
COMMENT ON COLUMN "public"."lrt_verify_job"."result" IS '验核结论文本：通过或不通过的原因与证据';
COMMENT ON COLUMN "public"."lrt_verify_job"."creator" IS '创建者UUID（执行者），关联uctoo_user.id，行级权限';
COMMENT ON COLUMN "public"."lrt_verify_job"."owner_user_id" IS '归属者（委派该任务的真人用户 uctoo_user.id）。与 creator 区分：creator 记执行者（agent 帐号），本列恒记归属真人；历史行允许 NULL。';
COMMENT ON COLUMN "public"."lrt_verify_job"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."lrt_verify_job"."updated_at" IS '更新时间';
COMMENT ON COLUMN "public"."lrt_verify_job"."deleted_at" IS '软删除时间，NULL=未删除';
COMMENT ON TABLE "public"."lrt_verify_job" IS '长程任务验核队列：宿主每回合结束后把验核请求持久化入队，作为事件驱动触发源与审计轨迹';

-- ----------------------------
-- Records of lrt_verify_job
-- ----------------------------

