-- ----------------------------
-- Table structure for sdd_projects
-- ----------------------------
DROP TABLE IF EXISTS "public"."sdd_projects";
CREATE TABLE "public"."sdd_projects" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "feature_name" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "title" varchar(256) COLLATE "pg_catalog"."default",
  "task_id" uuid,
  "current_stage" varchar(32) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'init',
  "status" varchar(20) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'running',
  "enable_research" bool NOT NULL DEFAULT false,
  "round" int4 NOT NULL DEFAULT 1,
  "payload" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz(6)
)
;
COMMENT ON TABLE "public"."sdd_projects" IS 'SDD规范驱动开发工程实例：feature_name唯一，current_stage取值 init/research/spec/design/task/code/test/done';
COMMENT ON COLUMN "public"."sdd_projects"."id" IS '主键ID';
COMMENT ON COLUMN "public"."sdd_projects"."feature_name" IS '功能名称（唯一标识）';
COMMENT ON COLUMN "public"."sdd_projects"."title" IS '工程标题';
COMMENT ON COLUMN "public"."sdd_projects"."task_id" IS '关联长程任务ID';
COMMENT ON COLUMN "public"."sdd_projects"."current_stage" IS '当前阶段(init/research/spec/design/task/code/test/done)';
COMMENT ON COLUMN "public"."sdd_projects"."status" IS '状态(running/paused/done/cancelled)';
COMMENT ON COLUMN "public"."sdd_projects"."enable_research" IS '是否启用研究阶段';
COMMENT ON COLUMN "public"."sdd_projects"."round" IS '当前轮次（revise时递增）';
COMMENT ON COLUMN "public"."sdd_projects"."payload" IS '扩展数据(JSONB)';
COMMENT ON COLUMN "public"."sdd_projects"."creator" IS '创建人';
COMMENT ON COLUMN "public"."sdd_projects"."owner_user_id" IS '所属用户ID（行级权限用）';
COMMENT ON COLUMN "public"."sdd_projects"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."sdd_projects"."updated_at" IS '更新时间';
COMMENT ON COLUMN "public"."sdd_projects"."deleted_at" IS '删除时间(软删除)';

-- ----------------------------
-- Records of sdd_projects
-- ----------------------------

