COMMENT ON COLUMN "public"."uctoo_user"."last_login_time" IS '最近一次登录时间';
COMMENT ON COLUMN "public"."uctoo_user"."remember_token" IS '是否记录token。用于再次自动登录';
COMMENT ON COLUMN "public"."uctoo_user"."updated_at" IS '更新时间';
